  .report-meta span {
    font-size: 12px;
    color: var(--text-secondary);
  }
  .report-meta span strong {
    color: var(--text-primary);
  }

  /* Layout */
  .container {
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 32px 64px;
  }

  /* Section headers */
  .section {
    margin-top: 48px;
  }
  .section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 20px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--border);
  }
  .section-number {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border-radius: 6px;
