  .badge-leo { background: rgba(63,185,80,0.15); color: var(--accent2); }
  .badge-meo { background: rgba(255,166,87,0.15); color: var(--accent5); }
  .badge-geo { background: rgba(210,168,255,0.15); color: var(--accent4); }
