  /* Text */
  p { color: var(--text-secondary); font-size: 13px; line-height: 1.7; margin-bottom: 12px; }
  p strong { color: var(--text-primary); }

  /* Conclusions */
  .insight-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin: 20px 0;
  }
  .insight-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 18px;
  }
  .insight-card h4 {
